    out.m02 = 0;
    out.m03 = 0;
    out.m04 = 0;
    out.m05 = 0;
    out.m06 = 0;
    out.m07 = 0;
    out.m08 = 0;
    out.m09 = 0;
    out.m10 = 0;
    out.m11 = 0;
    out.m12 = 0;
