      const a10 = a.m04;
      const a11 = a.m05;
      const a12 = a.m06;
      const a13 = a.m07;
      const a20 = a.m08;
      const a21 = a.m09;
      const a22 = a.m10;
      const a23 = a.m11;
      out.m00 = a00;
      out.m01 = a01;
      out.m02 = a02;
      out.m03 = a03;
      out.m04 = a10;
      out.m05 = a11;
      out.m06 = a12;
      out.m07 = a13;
      out.m08 = a20;
      out.m09 = a21;
      out.m10 = a22;
      out.m11 = a23;
      out.m12 = a00 * x + a10 * y + a20 * z + a.m12;
      out.m13 = a01 * x + a11 * y + a21 * z + a.m13;
      out.m14 = a02 * x + a12 * y + a22 * z + a.m14;
      out.m15 = a03 * x + a13 * y + a23 * z + a.m15;
