    const a02 = a.m02;
    const a03 = a.m03;
    const a10 = a.m04;
    const a11 = a.m05;
    const a12 = a.m06;
    const a13 = a.m07;
    const a20 = a.m08;
    const a21 = a.m09;
    const a22 = a.m10;
