    out.m03 = 0;
    out.m04 = 0;
    out.m05 = near * 2 * tb;
    out.m06 = 0;
    out.m07 = 0;
    out.m08 = (right + left) * rl;
    out.m09 = (top + bottom) * tb;
    out.m10 = (far + near) * nf;
